def train_markov(records, k=10):
    """Train Markov chain on binary strings"""
    transitions = {}
    for r in records:
        for i in range(len(r) - k):
            ctx = r[i:i+k]
            nxt = r[i+k]
            if ctx not in transitions:
                transitions[ctx] = {'0': 0.1, '1': 0.1} # Laplace smoothing
            transitions[ctx][nxt] += 1.0
    return transitions

def generate_from_markov(transitions, k=10, length=74):
    """Generate a new number based on Markov probabilities while preserving the core (prefix)"""
    # All Zone 2 numbers share a common prefix (core). Without it, hitting the x* funnel is impossible.
    prefix = "11111111110000001110010011001110000101010001101110011110"
    res = list(prefix)
    
    for _ in range(length - len(prefix)):
        cur_ctx = "".join(res[-k:])
        if cur_ctx in transitions:
            w0 = transitions[cur_ctx]['0']
            w1 = transitions[cur_ctx]['1']
            # Add a bit of randomness (temperature) for diversity
            if random.random() < 0.1:
                res.append(random.choice(['0', '1']))
            else:
                res.append(random.choices(['0', '1'], weights=[w0, w1])[0])
        else:
            res.append(random.choice(['0', '1']))
            
    res[-1] = '1' # Number must be odd
    return int("".join(res), 2)

