    found_zone2 = set()
    
    # 71-bit anchor (to check uniqueness)
    anchor = 2358909599867980429759 
    
    for attempt in range(1, 10001): 
        target_bits = random.randint(72, 78)
        candidate = generate_from_markov(transitions, k=K_ORDER, length=target_bits)
        
        peak_bits, _, _ = collatz_peak(candidate, max_steps=1000)
        
        if peak_bits == 140 and candidate not in found_zone2 and candidate != anchor:
            found_zone2.add(candidate)
            ratio = peak_bits / candidate.bit_length()
            print(f" [#{len(found_zone2)}] ZONE 2 FOUND! (Attempt {attempt})")
            print(f"   Bits: {candidate.bit_length()}")
            print(f"   Peak: {peak_bits}")
            print(f"   Ratio: {ratio:.4f}")
            print(f"   Number: {candidate}")
            print()
            
        if len(found_zone2) >= 3:
            break
            
    if not found_zone2:
        print("❌ Search failed. Please try again.")
